                    <div className="flex justify-between items-center mb-2 shrink-0">
                        <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest">Spending Velocity</h3>
                        <div className="relative">
                            <button 
                                onClick={(e) => toggleMenu(e, 'spending_menu')}
                                className="flex items-center gap-2 border border-white/10 rounded px-3 py-1.5 bg-slate-900 cursor-pointer hover:bg-slate-800 transition-colors"
                            >
                                <span className="text-[10px] font-bold text-slate-400 uppercase">
                                    Vs {spendingComparison === 'year' ? 'Last Year' : 'Last Month'}
                                </span>
                                <ChevronDown className="w-3 h-3 text-slate-500" />
                            </button>
                            {activeMenu === 'spending_menu' && (
                                <div className="absolute right-0 top-full mt-2 w-40 bg-slate-900 border border-white/10 rounded-xl shadow-xl z-20 overflow-hidden animate-fade-in">
                                    <button onClick={() => { setSpendingComparison('year'); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white uppercase tracking-wider">Vs Last Year</button>
                                    <button onClick={() => { setSpendingComparison('month'); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white uppercase tracking-wider">Vs Last Month</button>
                                </div>
                            )}
                        </div>
                    </div>
                    <div className="flex-1 w-full min-h-0 relative">
                        <ResponsiveContainer width="100%" height="100%">
                            <ComposedChart data={lineChartData} margin={{ top: 5, right: 10, left: -20, bottom: 20 }}>
                                <defs>
                                    <linearGradient id="colorThisMonth" x1="0" y1="0" x2="0" y2="1">
                                        <stop offset="5%" stopColor="#6366f1" stopOpacity={0.4}/>
                                        <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                    </linearGradient>
                                </defs>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#1e293b" />
                                <XAxis 
                                    dataKey="day" 
                                    stroke="#475569" 
                                    fontSize={10} 
                                    tickLine={false} 
                                    axisLine={false} 
                                    dy={10}
                                />
                                <YAxis 
                                    stroke="#475569" 
                                    fontSize={10} 
                                    tickLine={false} 
                                    axisLine={false} 
                                    tickFormatter={(val) => `$${val > 999 ? (val/1000).toFixed(1) + 'k' : val}`}
                                />
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.5)' }} 
                                    itemStyle={{ fontSize: '11px', fontWeight: 'bold', color: '#fff' }}
                                    formatter={(v: number) => formatCurrency(v)}
                                />
                                <Line type="monotone" dataKey="Comparison" stroke="#334155" strokeWidth={2} dot={false} strokeDasharray="5 5" />
                                <Area type="monotone" dataKey="ThisMonth" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorThisMonth)" />
                            </ComposedChart>
                        </ResponsiveContainer>
                    </div>
                    <div className="flex justify-center gap-6 mt-1 shrink-0 pb-2">
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-slate-700"></div>
                            <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{spendingComparison === 'year' ? 'Last Year' : 'Last Month'}</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_8px_#6366f1]"></div>
                            <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">This Month</span>
                        </div>
                    </div>
                </div>

            </div>

            {/* RIGHT SIDEBAR */}
            <div className="lg:col-span-4 flex flex-col gap-6 h-full">

                {/* Goal Vector - Card theme RED, Button theme INDIGO (Default Nova) */}
                <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 bg-slate-900/40 flex flex-col gap-6">
                    <div className="flex justify-between items-center">
                        <div className="flex items-center gap-3">
                            <div className="w-10 h-10 rounded-full bg-rose-500/20 flex items-center justify-center border border-rose-500/30">
                                <Target className="w-5 h-5 text-rose-400" />
