interface CashflowBetaProps {
  transactions: Transaction[];
  accounts: Account[];
  goals: Goal[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

const CashflowBeta: React.FC<CashflowBetaProps> = ({ transactions, accounts, goals, formatCurrency, userPlan }) => {
  const isElite = userPlan === 'ultra';

  const today = new Date();
  const currentMonth = today.getMonth();
  const currentYear = today.getFullYear();

  const data = useMemo(() => {
    const monthTxs = transactions.filter(t => {
      const d = new Date(t.date);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const incomeTxs = monthTxs.filter(t => t.type === TransactionType.INCOME);
    const totalIncome = incomeTxs.reduce((acc, t) => acc + t.amount, 0);

    // Group income by merchant/source for visual detail
    const incomeSources = incomeTxs.reduce((acc, t) => {
        acc[t.merchant] = (acc[t.merchant] || 0) + t.amount;
        return acc;
    }, {} as Record<string, number>);
    const sortedIncomeSources = Object.entries(incomeSources).sort((a, b) => (b[1] as number) - (a[1] as number)).slice(0, 3);

    const expenseMap = monthTxs
      .filter(t => t.type === TransactionType.EXPENSE)
      .reduce((acc, t) => {
        acc[t.category] = (acc[t.category] || 0) + t.amount;
        return acc;
      }, {} as Record<string, number>);

    const totalExpenses = (Object.values(expenseMap) as number[]).reduce((a, b) => a + b, 0);
    const savings = Math.max(0, totalIncome - totalExpenses);

    const categories = (Object.entries(expenseMap) as [string, number][])
      .sort((a, b) => b[1] - a[1])
      .slice(0, 5); // Top 5 expenses

    return { 
        income: totalIncome, 
        incomeSources: sortedIncomeSources,
        categories, 
        savings, 
        totalExpenses 
    };
  }, [transactions, currentMonth, currentYear]);

  // Handle empty state gracefully
  const hasData = data.income > 0 || data.totalExpenses > 0 || accounts.length > 0;

